var para = [];
var headingIds = Object.create(null);
function headingId(value) {
  var base = value.toLowerCase().replace(/[^a-z0-9\u3400-\u9fff]+/g, '-').replace(/^-|-$/g, '') || 'section';
  var id = base;
  var suffix = 2;
  while (headingIds[id]) id = base + '-' + suffix++;
  headingIds[id] = true;
  return id;
}

